export function slugify(text) {
  return text
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '') // Akzente entfernen (ä -> a)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function label(id, name) {
  return `${pad(id, 4)} ${slugify(name)}`;
}

